&lt;p data-ccp-border-between=&quot;0px none #000000&quot; data-ccp-padding-between=&quot;0px&quot;&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Cross&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Functional Partnership &amp;amp; Support:&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:360,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
